            # (unassigned is worse than any acceptable event)
            # w must have free seat or strictly prefer s over some assigned
            if occ[w] < capacities[w]:
                # blocking
                return False
            # check if w strictly prefers s over some assigned student
            s_tier = erank[(w, s)]
            if s_tier is None:
                continue
            for t in assigned:
                if assigned[t] != w:
                    continue
                t_tier = erank[(w, t)]
                if t_tier is None:
                    continue
                if s_tier < t_tier:
                    return False
