            return
        s = students[i]
        for e in options[i]:
            if e is not None:
                if occ[e] >= capacities[e]:
                    continue
                occ[e] += 1
                mapping[s] = e
                rec(i + 1)
                del mapping[s]
                occ[e] -= 1
            else:
                mapping[s] = None
                rec(i + 1)
                del mapping[s]

    rec(0)
    return results


